// === Tab: mySketch ===
const speed = 2.6

function setup()
{
	createCanvas(windowWidth, windowHeight);
	background(0); // 
	x = windowWidth/2
	y = windowHeight/2
	bots = []
	for (k=900; k--;)
	{
		bots.push(new bot(width/2, height/2))
	}
}

function draw()
{
	noStroke()
	fill("#00000009")
	rect(0,0,width,height)
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)))
	{
		bots[bots.length-1].x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
		bots[bots.length-1].y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
	}
	for (b=0; b<bots.length-1; b++)
	{
		bots[b].target(bots[b+1].x, bots[b+1].y)
		bots[b].draw()
	}
	bots[bots.length-1].target(bots[0].x, bots[0].y)
}

function bot(x, y)
{
	this.x = x
	this.y = y
	this.draw = function()
	{
		fill('white')
		stroke('gray')
		strokeWeight(.5)
		ellipse(this.x, this.y, 9, 9)
	}
	this.target = function(x,y)
	{
		this.x+=(x-this.x)/speed
		this.y+=(y-this.y)/speed
	}
}

